def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0xE804):return operation
    for offset in range(26,32):
        operation=operation.replace('(IX+#'+format(offset,'02X')+')','(IX + @FActionRecord.Unknown'+format(offset,'02X')+')')
    for literal,name in (('0B','LinkedIndex'),('0C','LinkFlags')):
        operation=operation.replace('(IY+#'+literal+')','(IY + @FActionRecord.'+name+')')
    for address,name in ((0xE794,'LoadLinkedRecordVectors'),(0xE6C7,'RecordAddressToIndex'),(0xEB41,'ToggleTargetOverlay')):
        operation=operation.replace('CALL #'+format(address,'04X'),'CALL @Action.'+name+'.Entry')
    for index,address in enumerate((0xD9B6,0xD7C4,0xD7A2)):
        operation=operation.replace('(#'+format(address,'04X')+')','(@ActionPatchedVectorState.Output'+str(index)+')')
    return operation.replace('CP #80','CP @ActionReuseConst.ReusableHigh')

